def get_language(request=None, user=None):
    language = None
    if request is not None:
        language = getattr(request, "site_language", None) or request.session.get("site_language")
        user = getattr(request, "user", user)
    if not language and user is not None and getattr(user, "is_authenticated", False):
        try:
            language = user.profile.preferred_language
        except Exception:
            language = None
    return language if language in SUPPORTED_LANGUAGES else "ar"


def tr(key, language="ar"):
    language = language if language in TRANSLATIONS else "ar"
    return TRANSLATIONS[language].get(key, TRANSLATIONS["en"].get(key, key))


def ui_for(language):
    language = language if language in TRANSLATIONS else "ar"
    return TRANSLATIONS[language]
